import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Reservations","description":"","frontmatter":{},"headers":[],"relativePath":"user/center/reservations.md","filePath":"user/center/reservations.md"}'),s={name:"user/center/reservations.md"};function i(r,e,l,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="reservations" tabindex="-1">Reservations <a class="header-anchor" href="#reservations" aria-label="Permalink to &quot;Reservations&quot;">​</a></h1><p><strong>Reservations</strong> lists every booking at your center. Filter by date, status or service, or use the <strong>calendar</strong>.</p><p>Every booking has a 6-character <strong>code</strong> (for example <code>K7QX2M</code>). A client can show it at the desk and you can look the booking up by it.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pending</strong></td><td>Booked, waiting for payment</td></tr><tr><td><strong>Confirmed</strong></td><td>Paid (or cash on arrival)</td></tr><tr><td><strong>Completed</strong></td><td>The visit happened</td></tr><tr><td><strong>No-show</strong></td><td>The client did not come</td></tr><tr><td><strong>Cancelled</strong></td><td>Cancelled; the slot is free again</td></tr></tbody></table><p>Pending, confirmed, completed and no-show bookings all <strong>use up capacity</strong>. Only cancelled ones free it.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>You need the reservations permission.</p><ul><li><strong>Create</strong> a booking for a client. Use <strong>quote</strong> first to check the price and availability.</li><li><strong>Cancel</strong> a booking.</li><li><strong>Complete</strong> or mark <strong>no-show</strong>, but only after the slot has started.</li><li><strong>Reschedule</strong> a pending or confirmed booking to another slot. The price must stay the same; if it would change, cancel and rebook. If the new slot is full you are told there are not enough places; confirm the move to book it anyway (this overbooks the slot). Other rules, such as opening hours, still apply.</li></ul><h2 id="cancelling-and-refunds" tabindex="-1">Cancelling and refunds <a class="header-anchor" href="#cancelling-and-refunds" aria-label="Permalink to &quot;Cancelling and refunds&quot;">​</a></h2><ul><li>Clients can cancel only until the cutoff set by the platform (a number of hours before the start). Staff are not bound by it.</li><li>An <strong>online</strong> payment is refunded automatically. If the refund cannot be made, the cancellation does not go through.</li><li>A <strong>manual</strong> payment is marked as needing a manual refund.</li><li><strong>Cash</strong> or unpaid bookings have nothing to refund.</li><li>A cancelled booking from a package gives the session back.</li><li>On a client&#39;s package you can book a session for them, add sessions, set or remove the trainer (training packages) and extend the expiry date. Extending an expired package that still has sessions makes it active again.</li><li>You can also extend a client&#39;s membership expiry date; an expired membership becomes active again. The packages that came with it keep their own dates.</li><li>Check a member in when they arrive; every check-in is added to the membership&#39;s log, which also lists the guests the member invited (with the visit created for each). Checking in does not change any booking, and only active memberships can be checked in.</li></ul><h2 id="unpaid-bookings" tabindex="-1">Unpaid bookings <a class="header-anchor" href="#unpaid-bookings" aria-label="Permalink to &quot;Unpaid bookings&quot;">​</a></h2><p>An online booking that is not paid within the hold time is cancelled automatically. If the payment arrives afterwards, it is refunded automatically.</p><h2 id="why-a-booking-is-refused" tabindex="-1">Why a booking is refused <a class="header-anchor" href="#why-a-booking-is-refused" aria-label="Permalink to &quot;Why a booking is refused&quot;">​</a></h2><p>Common reasons: the slot is full or in the past, the service is inactive, the client is blocked by your center, a block or closure overlaps, or the service type&#39;s booking option is switched off.</p>',15)])])}const p=t(s,[["render",i]]);export{u as __pageData,p as default};
